# Mathe: Gliederung (gl), handschriftliche Mitschrift (ms), Übungsblätter. Die Mitschrift wurde Seite für Seite als Bild gelesen
# (Texterkennung der Handschrift ist unbrauchbar); der fehlende Stoff steht in werkzeuge/einarbeiten/wima.py. Hier bleiben nur
# Texterkennungs-Reste, Schreibfehler und Organisatorisches.
DECKNAME[F] = {'gl': 'Gliederung', 'ms': 'Mitschrift'}
ok(F, 'gl/2', 'Matrizeninversion')                                  # Gliederungspunkt; inverse-matrix
kein(F, 'ms/2', 'Übungsaufgaben', 'Kennwort')                        # Zugang zum Kursraum
kein(F, 'ms/3', 'Vorbemerkung', 'Eirrationale', 'Zahlenly'); kein(F, 'ms/4', 'Anordnungsaxionen'); kein(F, 'ms/5', 'Granzwerte')
kein(F, 'ms/7', 'Zahlenhelobenheit'); kein(F, 'ms/9', 'Konvergester'); kein(F, 'ms/10', 'lan-bnineIN', 'Konvergest', 'Granvertinae')
ok(F, 'ms/10', 'Folgeglieder', 'Nennerfolge')                       # Quotient konvergenter Folgen (ab n0 ist b_n ≠ 0) steht in grenzwert-folge
kein(F, 'ms/14', 'Radikanten'); kein(F, 'ms/17', 'Zordnungsvorschrift'); kein(F, 'ms/18', 'x-Achsel'); ok(F, 'ms/18', 'Abzissenbezeichnung')
kein(F, 'ms/19', 'Gaußklammel'); kein(F, 'ms/21', 'Poktelle', 'Übungsaufgaben'); kein(F, 'ms/26', 'Mometrische')
kein(F, 'ms/28', 'Übungsaufgabe'); kein(F, 'ms/30', 'Übungsaufgabe'); ok(F, 'ms/32', 'Änderungsverhalten'); ok(F, 'ms/35', 'Höpitalsche')
